/* Kelas VIII — Semester 2 — Kisah Kesungguhan Ibadah Para Sahabat — 50 soal */
window.BSRegister({
'id':'k8-kisah-sahabat','grade':8,'semester':2,'order':11,
'title':'Kisah Kesungguhan Ibadah Para Sahabat',
'desc':'Kesungguhan ibadah Abu Bakar, Umar, Utsman, Ali, dan sahabat lain, dalil keutamaan mereka, adab terhadap sahabat, serta cara meneladani kesungguhan ibadah mereka dalam kehidupan pelajar.',
'kd':'Menganalisis kisah kesungguhan ibadah para sahabat Rasulullah, dan menampilkan keteladanan kesungguhan beribadah, kedermawanan dan keberanian mereka dalam kehidupan sehari-hari.',
'questions':[{level:'HOTS',indicator:'Menentukan kedudukan sahabat dalam Islam',text:'Kedudukan sahabat Rasulullah dalam Islam yang paling tepat adalah ...',options:['mereka merupakan orang yang hidup pada zaman Rasulullah sehingga memperoleh kedudukan secara otomatis','mereka merupakan orang yang paling banyak berjihad sehingga memperoleh kedudukan tertinggi di akhirat','mereka merupakan pemimpin umat setelah Rasulullah sehingga wajib diikuti dalam seluruh pendapat mereka','generasi terbaik yang menerima ajaran langsung lalu menyampaikannya'],answer:3,explanation:'Hadis menyebut bahwa sebaik-baik manusia adalah generasiku kemudian yang sesudahnya kemudian yang sesudahnya. Q.S. at-Taubah [9]: 100 berbunyi orang-orang yang terdahulu lagi yang pertama-tama masuk Islam dari golongan Muhajirin dan Ansar serta orang-orang yang mengikuti mereka dengan baik maka Allah ridha kepada mereka dan mereka pun ridha kepada Allah. Hadis juga menyebut bahwa janganlah kalian mencela sahabatku karena seandainya salah seorang dari kalian menginfakkan emas sebesar gunung Uhud maka tidak akan menyamai satu mud infak salah seorang dari mereka dan tidak pula separuhnya. Hadis menyebut bahwa Allah memilih para sahabat bagi Nabi-Nya. Hadis juga menyebut bahwa mencintai kaum Ansar merupakan tanda iman dan membenci mereka merupakan tanda nifaq. Q.S. al-Fath [48]: 29 menggambarkan para sahabat bersama Rasulullah bersikap keras terhadap orang kafir dan berkasih sayang sesama mereka. Adapun kedudukan mereka bukan otomatis karena terdapat sahabat yang lebih utama dari yang lain sesuai dengan keimanan dan amalnya, dan mengikuti pendapat mereka dilakukan dengan dasar dalil bukan karena kedudukan pribadi mereka.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan ibadah Abu Bakar',text:'Abu Bakar dikenal sebagai sahabat yang paling utama dan paling banyak ibadahnya. Analisis yang paling tepat terhadap kesungguhan ibadah beliau adalah ...',options:['kesungguhan beliau berupa banyaknya ibadah sunah yang dilakukannya sepanjang malam','kesungguhan beliau berupa banyaknya hadis yang diriwayatkannya sehingga ilmunya paling luas','kesungguhan beliau berupa keberaniannya memimpin pasukan dalam seluruh peperangan','membenarkan tanpa ragu, mengorbankan harta, dan menemani di gua'],answer:3,explanation:'Q.S. at-Taubah [9]: 40 menceritakan Abu Bakar yang menemani Rasulullah di dalam gua ketika Rasulullah berkata kepadanya janganlah bersedih hati sesungguhnya Allah bersama kita, sehingga Allah menurunkan ketenangan kepadanya dan memperkuatnya dengan bala tentara yang tidak terlihat. Hadis juga menyebut bahwa Rasulullah bersabda kepada Abu Bakar ketika ia menangis di sisi Rasulullah pada saat sakit yang membawa kepada wafatnya beliau. Hadis menyebut bahwa tidak ada harta yang bermanfaat bagiku seperti harta Abu Bakar, dan Abu Bakar menangis lalu berkata apakah diriku dan hartaku bukan untukmu wahai Rasulullah. Hadis juga menyebut bahwa apabila seseorang ditimbang dengan Abu Bakar maka Abu Bakar lebih berat dalam satu riwayat tentang keutamaannya. Sejarah mencatat Abu Bakar memerdekakan Bilal dan beberapa hamba sahaya lain yang disiksa karena imannya dengan membayar harganya. Q.S. al-Lail [92]: 17-18 menyebut orang yang paling bertakwa yang dijauhkan dari neraka yaitu yang memberikan hartanya untuk menyucikan diri. Hadis menyebut bahwa Abu Bakar merupakan orang pertama yang membenarkan peristiwa Isra Mikraj sehingga memperoleh sebutan as-Siddiq. Adapun Abu Bakar bukan perawi hadis terbanyak karena Abu Hurairah lebih banyak meriwayatkan.'},
{level:'HOTS',indicator:'Menentukan kesungguhan ibadah Umar bin Khattab',text:'Kesungguhan ibadah Umar bin Khattab yang paling tepat adalah ...',options:['tegas menegakkan keadilan dan sederhana walaupun memegang kekuasaan','kesungguhan beliau berupa banyaknya sahabat yang belajar kepadanya sehingga ilmunya tersebar luas','kesungguhan beliau berupa keberaniannya berperang sendiri dalam seluruh peperangan','kesungguhan beliau berupa banyaknya harta yang disedekahkan sehingga tidak memiliki harta lagi'],answer:0,explanation:'Hadis menyebut bahwa Rasulullah bersabda sesungguhnya Allah menjadikan kebenaran pada lisan Umar dan hatinya. Hadis juga menyebut kisah Umar yang berkata wahai Rasulullah sesungguhnya aku telah beramal untuk memperoleh kedudukan lalu Rasulullah menjelaskan keutamaan amal yang ikhlas, yang menunjukkan kehati-hatian beliau dalam niat. Sejarah mencatat Umar memikul sendiri karung gandum untuk seorang ibu yang memasak batu untuk menenangkan anak-anaknya yang kelaparan dan menolak bantuan pembantunya dengan berkata apakah engkau akan memikul dosaku pada hari kiamat. Sejarah juga mencatat pakaian Umar yang bertambal walaupun beliau merupakan khalifah dan menolak memakai pakaian yang lebih baik ketika menerima utusan dari Persia. Hadis juga menyebut bahwa Umar termasuk orang yang ilhamnya sering bertepatan dengan ketentuan yang kemudian turun wahyu menyetujuinya seperti dalam persoalan hijab dan persoalan salat di Maqam Ibrahim. Q.S. al-Hajj [22]: 41 menggambarkan orang yang apabila diberi kekuasaan di bumi mendirikan salat, menunaikan zakat, menyuruh berbuat makruf, dan mencegah dari yang mungkar.'},
{level:'HOTS',indicator:'Menganalisis kedermawanan Utsman bin Affan',text:'Utsman bin Affan dikenal sebagai sahabat yang paling dermawan dalam menyumbangkan hartanya. Analisis yang paling tepat terhadap kedermawanan beliau adalah ...',options:['kedermawanan beliau berupa pemberian kepada kerabatnya saja sehingga keluarga besarnya terbantu','kedermawanan beliau berupa kesediaannya memberikan seluruh hartanya lalu tidak memiliki apa pun seperti Abu Bakar','membeli sumur untuk diwakafkan dan membiayai pasukan Perang Tabuk','kedermawanan beliau berupa pemberian kepada seluruh orang yang meminta tanpa mempertimbangkan keperluannya'],answer:2,explanation:'Sejarah mencatat Utsman membeli sumur Raumah yang airnya dijual oleh pemiliknya lalu mewakafkannya untuk kaum muslimin setelah Rasulullah menganjurkan siapa yang membeli sumur itu maka baginya surga. Sejarah juga mencatat Utsman membiayai pasukan dalam Perang Tabuk dengan seribu dinar serta unta dan kuda, dan Rasulullah bersabda tidak ada yang membahayakan Utsman apa yang dilakukannya setelah hari ini. Hadis juga menyebut bahwa Utsman merupakan orang yang paling pemalu di antara umat Rasulullah dan bahwa para malaikat malu kepadanya Utsman. Q.S. al-Baqarah [2]: 261 memberi perumpamaan orang yang menafkahkan hartanya di jalan Allah seperti satu biji yang menumbuhkan tujuh tangkai dan pada setiap tangkai terdapat seratus biji. Q.S. al-Hadid [57]: 10 menyebut perbedaan kedudukan antara orang yang berinfak sebelum penaklukan Makkah dan sesudahnya. Hadis juga menyebut bahwa sebaik-baik harta adalah harta yang berada di tangan orang saleh. Adapun kedermawanan Utsman bukan pemberian kepada seluruh orang yang meminta tanpa pertimbangan karena pemberian yang benar disesuaikan dengan keperluan dan manfaat.'},
{level:'HOTS',indicator:'Menentukan kesungguhan ibadah Ali bin Abi Thalib',text:'Kesungguhan ibadah Ali bin Abi Thalib yang paling tepat adalah ...',options:['kesungguhan beliau berupa kesediaannya berperang sendiri melawan seluruh musuh tanpa bantuan pasukan','kesungguhan beliau berupa keberaniannya menggantikan Rasulullah tidur di tempat tidurnya ketika malam hijrah','kesungguhan beliau berupa banyaknya harta yang dimilikinya sehingga dapat membiayai seluruh keperluan umat','berani menggantikan Rasulullah di ranjang dan berilmu sangat luas'],answer:3,explanation:'Sejarah mencatat Ali menggantikan Rasulullah tidur di tempat tidurnya pada malam hijrah dan Rasulullah memerintahkannya menyampaikan amanah kepada pemiliknya keesokan harinya, sehingga Q.S. al-Baqarah [2]: 207 menyebut bahwa di antara manusia ada orang yang mengorbankan dirinya karena mencari keridhaan Allah. Q.S. al-Insan [76]: 8-9 menyebut orang yang memberikan makanan yang disukainya kepada orang miskin, anak yatim, dan tawanan sambil berkata sesungguhnya kami memberi makanan kepadamu hanyalah untuk mengharapkan keridhaan Allah dan kami tidak mengharapkan balasan dan ucapan terima kasih darimu, dan para mufasir menyebut bahwa ayat itu turun berkaitan dengan Ali, Fatimah, dan keluarga mereka. Hadis menyebut bahwa Rasulullah bersabda aku merupakan kota ilmu dan Ali merupakan pintunya. Hadis juga menyebut keutamaan Ali dalam Perang Khaibar ketika Rasulullah menyerahkan bendera kepadanya. Sejarah mencatat kesederhanaan Ali ketika menjadi khalifah dan keadilannya dalam memutuskan perkara walaupun terhadap pihak yang tidak menyukainya. Adapun Ali bukan orang yang paling banyak hartanya dan keberaniannya dalam peperangan selalu bersama pasukan kaum muslimin bukan berperang sendiri tanpa bantuan.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan ibadah Bilal bin Rabah',text:'Bilal bin Rabah disiksa karena imannya tetapi tetap teguh mengucapkan kalimat tauhid. Analisis yang paling tepat terhadap kesungguhan ibadah beliau adalah ...',options:['kesungguhan beliau berupa keberaniannya melawan pihak yang menyiksanya hingga memperoleh kemerdekaan','kesungguhan beliau berupa kesediaannya menyembunyikan keimanannya hingga keadaan aman','teguh mempertahankan iman walaupun disiksa dengan sangat berat','kesungguhan beliau berupa banyaknya harta yang diperolehnya setelah merdeka sehingga dapat membantu kaum muslimin'],answer:2,explanation:'Sejarah mencatat Bilal disiksa dengan diletakkan batu besar di dadanya di bawah terik matahari tetapi tetap mengucapkan ahad ahad yang berarti Esa, Esa, hingga Abu Bakar memerdekakannya dengan membayar harganya. Q.S. an-Nahl [16]: 106 menyebut bahwa orang yang kafir kepada Allah setelah beriman kecuali orang yang dipaksa sedangkan hatinya tetap tenang dengan iman, tetapi orang yang melapangkan dadanya untuk kekufuran maka bagi mereka kemurkaan Allah, sehingga menyembunyikan keyakinan karena paksaan dibolehkan tetapi Bilal memilih keteguhan walaupun berat. Hadis juga menyebut kisah Rasulullah yang bertanya kepada Bilal tentang amal yang paling diharapkan pahalanya karena Rasulullah mendengar suara terompahnya di surga, lalu Bilal menjawab bahwa ia tidak pernah berwudu pada waktu malam atau siang melainkan salat dengan wudu itu sebanyak yang ditetapkan baginya. Sejarah mencatat Bilal tidak sanggup mengumandangkan azan di Madinah setelah Rasulullah wafat karena kesedihannya. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Adapun Bilal tidak melawan pihak yang menyiksanya karena keadaannya sebagai hamba sahaya yang tidak berdaya, dan beliau bukan orang yang banyak hartanya.'},
{level:'HOTS',indicator:'Menentukan kesungguhan ibadah para sahabat dalam salat malam',text:'Kesungguhan ibadah para sahabat dalam salat malam yang paling tepat adalah ...',options:['melaksanakan salat malam sebanyak mungkin pada satu malam lalu berhenti pada malam berikutnya karena lelah','melaksanakan salat malam hanya pada bulan Ramadan agar memperoleh keutamaan bulan itu','salat malam teratur dengan kehadiran hati bukan sekadar panjang waktu','melaksanakan salat malam sepanjang malam tanpa tidur setiap hari'],answer:2,explanation:'Hadis menyebut kisah Abdullah bin Amr yang berpuasa setiap hari dan salat sepanjang malam lalu Rasulullah menganjurkan berpuasa tiga hari dalam sebulan dan salat serta tidur, kemudian terjadi tawar-menawar hingga Rasulullah menetapkan berpuasa sehari dan berbuka sehari serta membagi malam untuk tidur, ibadah, dan membaca Al-Quran, dan Rasulullah menyebut bahwa puasa yang paling dicintai Allah adalah puasa Dawud dan salat yang paling dicintai Allah adalah salat Dawud yang tidur separuh malam, beribadah sepertiganya, dan tidur seperenamnya. Hadis juga menyebut bahwa Rasulullah salat malam hingga kedua kakinya bengkak dan ketika ditanya mengapa beliau melakukan itu padahal dosa-dosanya telah diampuni beliau menjawab tidakkah aku ingin menjadi hamba yang bersyukur. Hadis juga menyebut bahwa salat yang paling utama setelah salat wajib adalah salat malam. Hadis menganjurkan amal yang berkelanjutan walaupun sedikit dan menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Adapun melaksanakan sepanjang malam setiap hari bukan cara yang diajarkan karena Rasulullah melarang membebani diri.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan para sahabat dalam bersedekah',text:'Para sahabat bersedekah dalam keadaan lapang maupun sempit. Analisis yang paling tepat terhadap kesungguhan mereka dalam bersedekah adalah ...',options:['kesungguhan mereka berupa pemberian ketika memperoleh harta yang banyak sehingga tidak memberi dalam keadaan sempit','kesungguhan mereka berupa pemberian seluruh harta sehingga tidak memiliki apa pun untuk keluarga','kesungguhan mereka berupa pemberian hanya kepada kerabat sehingga keluarga besar mereka terbantu','memberi dari yang dimiliki walaupun sedikit dengan ketulusan hati'],answer:3,explanation:'Q.S. Ali Imran [3]: 92 berbunyi kamu tidak akan memperoleh kebaikan hingga kamu menafkahkan sebagian dari harta yang kamu cintai. Q.S. al-Baqarah [2]: 273 menggambarkan orang yang tidak mampu berusaha di bumi dan disangka kaya oleh orang yang tidak mengetahui keadaannya karena mereka menjaga diri dari meminta-minta. Hadis juga menyebut tujuh golongan yang dinaungi Allah pada hari yang tidak ada naungan kecuali naungan-Nya di antaranya orang yang bersedekah lalu menyembunyikannya sehingga tangan kirinya tidak mengetahui apa yang diinfakkan tangan kanannya. Sejarah mencatat Abu Bakar menyedekahkan seluruh hartanya dan Umar menyedekahkan separuhnya ketika Rasulullah menganjurkan bersedekah. Q.S. al-Hasyr [59]: 9 menggambarkan kaum Ansar yang mengutamakan orang lain atas diri mereka walaupun diri mereka memerlukan dan menyebut bahwa siapa yang dipelihara dari kekikiran maka mereka itulah orang yang beruntung. Q.S. al-Insan [76]: 8-9 menggambarkan pemberian makanan kepada orang miskin, anak yatim, dan tawanan tanpa mengharapkan balasan. Adapun memberi kepada kerabat memperoleh tambahan pahala silaturahmi tetapi para sahabat memberi kepada seluruh pihak yang memerlukan.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam menuntut ilmu',text:'Kesungguhan para sahabat dalam menuntut ilmu yang paling tepat adalah ...',options:['menghafal seluruh Al-Quran dan seluruh hadis dalam waktu yang singkat','menunggu hingga Rasulullah menjelaskan tanpa bertanya agar tidak mengganggu beliau','meninggalkan pekerjaan dan keluarga untuk belajar kepada Rasulullah sepanjang waktu','setia menghadiri majelis, menghafal hadis, dan mengamalkannya'],answer:3,explanation:'Sejarah mencatat Umar dan seorang tetangganya dari kaum Ansar bergantian menghadiri majelis Rasulullah karena keduanya memiliki kebun yang harus diurusi, dan apabila salah seorang hadir maka ia menyampaikan kepada yang lain apa yang diperolehnya. Hadis juga menyebut bahwa barangsiapa menempuh jalan untuk mencari ilmu maka Allah mudahkan baginya jalan menuju surga. Q.S. an-Nahl [16]: 43 memerintahkan bertanya kepada ahli pengetahuan apabila tidak mengetahui. Hadis juga menyebut bahwa ilmu tidak diperoleh kecuali dengan tawadu dan memperhatikan. Hadis menganjurkan mencatat ilmu dengan menulis. Hadis menyebut bahwa barangsiapa ditanya tentang suatu ilmu lalu menyembunyikannya maka akan dipakaikan kendali dari api pada hari kiamat, sehingga menyampaikan ilmu kepada generasi berikutnya merupakan kewajiban. Q.S. as-Saff [61]: 2-3 mengecam orang yang mengatakan apa yang tidak dikerjakannya, sehingga mengamalkan ilmu merupakan bagian dari kesungguhan menuntutnya. Adapun meninggalkan pekerjaan dan keluarga bukan cara yang diajarkan karena Rasulullah mengajarkan memberikan hak kepada tubuh, keluarga, dan pekerjaan.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan para sahabat dalam berjihad',text:'Para sahabat mengikuti seluruh peperangan bersama Rasulullah dengan kesungguhan yang tinggi. Analisis yang paling tepat terhadap kesungguhan mereka dalam berjihad adalah ...',options:['kesungguhan mereka berupa keberanian berperang walaupun tanpa izin pimpinan karena keadaan mendesak','kesungguhan mereka berupa keberanian menghadapi musuh yang lebih banyak jumlahnya tanpa persiapan','kesungguhan mereka berupa kesediaan berperang sepanjang tahun tanpa kembali kepada keluarga','mengorbankan harta dan jiwa serta taat kepada pimpinan perang'],answer:3,explanation:'Q.S. at-Taubah [9]: 41 berbunyi berangkatlah kamu baik dalam keadaan merasa ringan maupun merasa berat dan berjihadlah dengan harta dan jiwamu di jalan Allah. Q.S. at-Taubah [9]: 25-26 menceritakan Perang Hunain ketika jumlah yang banyak tidak bermanfaat dan sebagian besar pasukan mundur lalu Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang beriman serta menurunkan bala tentara yang tidak terlihat. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah dalam urusan kemudian apabila telah membulatkan tekad maka bertawakallah kepada Allah, sehingga ketaatan kepada pimpinan merupakan bagian dari adab jihad. Hadis juga menyebut bahwa Rasulullah bersabda tidak beriman seseorang hingga aku lebih dicintainya daripada hartanya, keluarganya, dan seluruh manusia. Hadis menyebut bahwa amal yang paling utama setelah iman adalah jihad di jalan Allah. Hadis juga melarang berperang tanpa izin pimpinan dan menganjurkan persiapan sebagaimana Q.S. al-Anfal [8]: 60 yang memerintahkan mempersiapkan kekuatan dan kuda yang ditambat untuk menghadapi musuh. Adapun berperang sepanjang tahun tanpa kembali kepada keluarga bukan ketentuan karena jihad memiliki ketentuan waktunya dan keluarga memiliki hak atas anggotanya.'},
{level:'HOTS',indicator:'Menentukan adab terhadap sahabat Rasulullah',text:'Adab terhadap sahabat Rasulullah yang paling tepat adalah ...',options:['tidak membicarakan sahabat sama sekali agar tidak timbul kekeliruan dalam penilaian','mencintai seluruhnya, tidak mencela, dan mengambil ilmu dari riwayatnya','membicarakan perselisihan di antara mereka untuk mengetahui siapa yang benar agar umat tidak keliru mengikutinya','membela sahabat yang paling disukai dan tidak membela sahabat yang lain karena yang penting adalah membela kebenaran'],answer:1,explanation:'Hadis menyebut bahwa janganlah kalian mencela sahabatku karena seandainya salah seorang dari kalian menginfakkan emas sebesar gunung Uhud maka tidak akan menyamai satu mud infak salah seorang dari mereka dan tidak pula separuhnya. Hadis juga menyebut bahwa Allah Allah terhadap sahabatku, janganlah kalian menjadikan mereka sasaran cercaan setelahku, maka barangsiapa mencintai mereka maka dengan cintaku ia mencintai mereka dan barangsiapa membenci mereka maka dengan benciku ia membenci mereka. Q.S. at-Taubah [9]: 100 menyebut keridhaan Allah kepada Muhajirin, Ansar, dan orang yang mengikuti mereka dengan baik. Hadis juga menyebut bahwa para sahabat merupakan bintang sehingga apabila bintang itu hilang maka sebagian besar yang dijanjikan kepada agama akan hilang. Para ulama menetapkan bahwa perselisihan yang terjadi di antara sahabat tidak dibicarakan untuk menyalahkan melainkan diserahkan kepada Allah karena mereka berijtihad dan memperoleh pahala atas ijtihadnya. Q.S. al-Hasyr [59]: 10 mengajarkan doa bagi orang beriman yang datang sesudah mereka agar tidak terdapat kedengkian dalam hati terhadap orang beriman. Adapun memilih membela sebagian sahabat bukan adab karena seluruh sahabat berhak atas cinta dan penghormatan, dan membicarakan perselisihan mereka untuk menilai siapa yang benar bukan kedudukan umat yang datang kemudian.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesederhanaan para sahabat walaupun berkedudukan tinggi',text:'Para sahabat hidup sederhana walaupun ada yang memegang kekuasaan tertinggi dan ada yang memiliki harta yang banyak. Analisis yang paling tepat terhadap hikmah kesederhanaan tersebut adalah ...',options:['kesederhanaan membuktikan kedudukan bukan tujuan melainkan sarana','hikmahnya agar mereka tidak disangka mengumpulkan harta untuk kepentingan pribadi','hikmahnya agar mereka dapat memberikan seluruh hartanya kepada umat tanpa menyisakan untuk keluarga','hikmahnya karena kekayaan merupakan tanda kecintaan Allah kepada hamba-Nya sehingga mereka menghindari kekayaan'],answer:0,explanation:'Sejarah mencatat Umar memakai pakaian yang bertambal walaupun merupakan khalifah dan menolak saran untuk memakai pakaian yang lebih baik ketika menerima utusan dari Persia. Sejarah juga mencatat Abu Bakar yang tetap berdagang setelah menjadi khalifah hingga para sahabat menetapkan gaji untuknya dari baitul mal karena perdagangannya mengganggu urusan umat. Hadis juga menyebut bahwa dunia bagi Rasulullah hanya seperti pengendara yang berteduh di bawah pohon lalu pergi meninggalkannya. Hadis menyebut bahwa kekayaan yang hakiki bukan banyaknya harta melainkan kekayaan jiwa. Q.S. al-Hadid [57]: 20 menyebut bahwa kehidupan dunia hanyalah permainan dan kelengahan serta perhiasan dan bermegah-megahan. Hadis juga menyebut bahwa sebaik-baik harta adalah harta yang berada di tangan orang saleh, sehingga memiliki harta yang banyak dibolehkan apabila digunakan untuk kepentingan umat. Hadis menganjurkan meninggalkan ahli waris dalam keadaan berkecukupan, sehingga kesederhanaan bukan berarti tidak menyisakan untuk keluarga.'},
{level:'HOTS',indicator:'Menentukan cara meneladani kesungguhan ibadah Abu Bakar bagi pelajar',text:'Cara meneladani kesungguhan ibadah Abu Bakar bagi seorang pelajar adalah ...',options:['menyembunyikan seluruh amal kebaikan agar tidak diketahui oleh teman seperti Abu Bakar menyembunyikan sedekahnya','tidak mengikuti kegiatan sekolah yang bertepatan dengan waktu ibadah sunah agar dapat melaksanakan ibadah sunah','menyedekahkan seluruh uang saku agar memperoleh keutamaan seperti Abu Bakar','membenarkan tanpa ragu, bersedekah rutin, dan bersegera dalam kebaikan'],answer:3,explanation:'Hadis menyebut bahwa Abu Bakar merupakan orang pertama yang membenarkan peristiwa Isra Mikraj tanpa keraguan sehingga memperoleh sebutan as-Siddiq. Hadis juga menganjurkan bersegera dalam kebaikan sebagaimana Q.S. al-Muminun [23]: 61 yang menyebut bahwa mereka bersegera dalam kebaikan dan mereka adalah orang-orang yang lebih dahulu memperolehnya. Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga menyisihkan uang saku secara teratur lebih utama daripada menyedekahkan seluruhnya sekali lalu berhenti. Hadis juga menganjurkan membela orang yang dizalimi dan menyebut bahwa tolonglah saudaramu yang menzalimi dan yang dizalimi. Hadis menyebut bahwa salat merupakan amal yang paling dicintai Allah apabila dilaksanakan pada waktunya. Hadis juga menganjurkan menyembunyikan amal sunah tetapi memperlihatkan amal yang dapat menjadi teladan bagi orang lain apabila tidak menimbulkan riya, sehingga menyembunyikan seluruh amal bukan keharusan. Adapun tidak mengikuti kegiatan sekolah untuk melaksanakan ibadah sunah bukan cara yang tepat karena kewajiban belajar didahulukan atas ibadah sunah.'},
{level:'HOTS',indicator:'Menganalisis cara meneladani ketegasan Umar dalam menegakkan kebenaran',text:'Umar dikenal tegas dalam menegakkan kebenaran walaupun terhadap pihak yang dekat dengannya. Analisis yang paling tepat terhadap cara meneladani ketegasan tersebut bagi seorang pelajar adalah ...',options:['bersikap tegas terhadap seluruh teman agar tidak ada yang berani melanggar','menyampaikan pelanggaran teman kepada guru dengan cara yang mempermalukan teman itu agar ia jera','menyampaikan kebenaran tegas tanpa memihak teman yang bersalah','tidak berteman dengan siapa pun agar tidak terpengaruh dalam memutuskan persoalan'],answer:2,explanation:'Hadis menyebut bahwa Rasulullah bersabda sesungguhnya Allah menjadikan kebenaran pada lisan Umar dan hatinya. Hadis juga menyebut bahwa jihad yang paling utama adalah menyampaikan kata yang benar di hadapan pemimpin yang zalim. Q.S. al-Maidah [5]: 8 memerintahkan berlaku adil dan melarang kebencian terhadap suatu kaum mendorong berlaku tidak adil. Q.S. an-Nisa [4]: 135 memerintahkan menjadi saksi karena Allah walaupun terhadap diri sendiri, ibu bapak, dan kerabat. Hadis juga menyebut bahwa sombong adalah menolak kebenaran dan meremehkan manusia, sehingga ketegasan dalam kebenaran bukan bentuk kesombongan apabila disertai kelembutan cara. Hadis menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Hadis juga menganjurkan menasihati secara pribadi karena nasihat di depan umum terasa seperti penghinaan, sehingga menyampaikan pelanggaran dengan cara mempermalukan bukan ketegasan yang diajarkan. Adapun tidak berteman dengan siapa pun bukan cara meneladani ketegasan karena Umar tetap memiliki banyak sahabat dan tetap menjaga hubungan baik sambil menegakkan kebenaran.'},
{level:'HOTS',indicator:'Menentukan cara meneladani kedermawanan Utsman bagi pelajar',text:'Cara meneladani kedermawanan Utsman bin Affan bagi seorang pelajar adalah ...',options:['menyisihkan uang saku rutin dan menyumbang tanpa mengharapkan pujian','memberi dengan jumlah yang besar sekali dalam setahun agar dikenal sebagai orang yang dermawan','memberi kepada teman yang paling dekat saja agar hubungan menjadi lebih erat','menyedekahkan seluruh uang saku setiap bulan agar memperoleh pahala seperti Utsman'],answer:0,explanation:'Hadis juga menyebut bahwa tujuh golongan dinaungi Allah pada hari yang tidak ada naungan kecuali naungan-Nya di antaranya orang yang bersedekah lalu menyembunyikannya sehingga tangan kirinya tidak mengetahui apa yang diinfakkan tangan kanannya. Hadis juga menyebut bahwa janganlah meremehkan kebaikan sedikit pun walaupun hanya bertemu saudaramu dengan wajah yang berseri. Q.S. al-Baqarah [2]: 267 memerintahkan menafkahkan dari yang baik-baik dari apa yang diusahakan dan melarang memilih yang buruk untuk diberikan. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala sedekah dengan menyebut-nyebutnya dan menyakiti perasaan penerima. Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga menyisihkan secara teratur lebih utama daripada memberi dalam jumlah besar sekali dalam setahun. Hadis juga menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia, sehingga menyumbangkan tenaga dan kemampuan merupakan bentuk kedermawanan bagi yang tidak memiliki harta. Adapun memberi kepada teman yang paling dekat saja mengurangi makna kedermawanan karena kedermawanan Utsman ditujukan kepada kepentingan umat secara luas.'},
{level:'HOTS',indicator:'Menganalisis cara meneladani keilmuan Ali bin Abi Thalib',text:'Ali bin Abi Thalib dikenal sebagai sahabat yang paling berilmu di antara yang muda dan paling berani dalam menyatakan kebenaran. Analisis yang paling tepat terhadap cara meneladani keduanya bagi seorang pelajar adalah ...',options:['belajar sungguh-sungguh sejak muda dan berani menyatakan kebenaran','tidak menyampaikan pendapat yang berbeda dari pendapat mayoritas agar tidak timbul perselisihan','belajar hanya ilmu agama karena ilmu lain tidak berkaitan dengan kedudukan di akhirat','belajar sebanyak mungkin agar dapat menjawab seluruh pertanyaan teman'],answer:0,explanation:'Hadis menyebut bahwa Rasulullah bersabda aku merupakan kota ilmu dan Ali merupakan pintunya. Hadis juga menyebut bahwa ilmu tidak diperoleh kecuali dengan tawadu dan memperhatikan. Hadis menyebut bahwa apabila seseorang menganggap dirinya berilmu maka ia adalah orang bodoh, sehingga tidak merasa cukup dengan ilmu yang dimiliki merupakan tanda kesungguhan. Q.S. as-Saff [61]: 2-3 mengecam orang yang mengatakan apa yang tidak dikerjakannya, sehingga mengamalkan ilmu sebelum menyampaikan merupakan adab yang penting. Q.S. al-Maidah [5]: 8 memerintahkan berlaku adil dan melarang kebencian mendorong berlaku tidak adil. Hadis juga menyebut bahwa jihad yang paling utama adalah menyampaikan kata yang benar. Q.S. az-Zumar [39]: 9 menyebut apakah sama orang yang mengetahui dengan orang yang tidak mengetahui. Hadis menganjurkan menuntut ilmu dan menyebut bahwa barangsiapa menempuh jalan untuk mencari ilmu maka Allah mudahkan baginya jalan menuju surga, sehingga ilmu agama dan ilmu yang bermanfaat bagi umat sama-sama dianjurkan selama tidak bertentangan dengan ketentuan agama.'},
{level:'HOTS',indicator:'Menentukan kesungguhan ibadah para sahabat dalam membaca Al-Quran',text:'Kesungguhan ibadah para sahabat dalam membaca Al-Quran yang paling tepat adalah ...',options:['membaca Al-Quran hanya pada bulan Ramadan agar memperoleh keutamaan bulan itu bersama kaum muslimin','membaca Al-Quran dengan cepat agar dapat menyelesaikan seluruhnya dalam waktu singkat','membaca tartil dengan makna lalu menghafal dan mengamalkannya','membaca Al-Quran sebanyak mungkin dalam satu hari agar memperoleh pahala yang besar'],answer:2,explanation:'Sejarah mencatat Tamim ad-Dari dan sahabat lain yang mengulang satu ayat sepanjang malam karena tersentuh oleh kandungannya. Q.S. al-Muzzammil [73]: 4 memerintahkan membaca Al-Quran dengan tartil. Hadis juga menyebut bahwa kaum itu mempelajari sepuluh ayat dari Rasulullah lalu tidak berpindah kepada sepuluh ayat berikutnya hingga memahami apa yang terkandung di dalamnya dan mengamalkannya. Hadis menyebut bahwa orang yang mahir membaca Al-Quran bersama para malaikat yang mulia lagi taat dan orang yang membacanya dengan terbata-bata serta mengalami kesulitan memperoleh dua pahala. Hadis juga menganjurkan memperindah suara dalam membaca Al-Quran dan menyebut bahwa hiasilah Al-Quran dengan suara kalian. Hadis melarang meninggikan suara dalam bacaan ketika dapat mengganggu orang yang sedang salat. Hadis juga menganjurkan membaca Al-Quran secara teratur dan menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Adapun membaca dengan cepat untuk menyelesaikan banyak bukan cara yang dianjurkan karena mengurangi perhatian terhadap makna, dan membaca hanya pada Ramadan mengurangi keteraturan yang dianjurkan.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan ibadah para sahabat walaupun dosanya telah diampuni',text:'Rasulullah salat malam hingga kedua kakinya bengkak walaupun dosa-dosanya yang telah lalu dan yang akan datang telah diampuni. Analisis yang paling tepat terhadap hikmah kesungguhan ibadah tersebut adalah ...',options:['ibadah sungguh-sungguh merupakan wujud syukur bukan sekadar mencari ampunan','hikmahnya agar umat tidak merasa cukup dengan amal yang sedikit karena amal Rasulullah yang banyak tidak mengurangi kedudukannya','hikmahnya agar umat mengetahui bahwa ibadah yang banyak menghasilkan ampunan','hikmahnya karena ibadah malam merupakan satu-satunya ibadah yang menghasilkan ampunan dosa'],answer:0,explanation:'Hadis menyebut bahwa Rasulullah salat malam hingga kedua kakinya bengkak lalu Aisyah bertanya mengapa engkau melakukan ini wahai Rasulullah padahal Allah telah mengampuni dosamu yang telah lalu dan yang akan datang, lalu beliau menjawab tidakkah aku ingin menjadi hamba yang bersyukur. Q.S. al-Furqan [25]: 64 menggambarkan hamba Tuhan Yang Maha Pengasih yang melewati malam dengan sujud dan berdiri kepada Tuhan mereka. Q.S. as-Sajdah [32]: 16-17 menyebut bahwa lambung mereka jauh dari tempat tidurnya karena berdoa kepada Tuhan mereka dengan rasa takut dan harap. Hadis juga menyebut bahwa salat yang paling utama setelah salat wajib adalah salat malam. Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. Ibrahim [14]: 7 menyebut bahwa apabila bersyukur maka Allah menambah nikmat. Adapun ampunan diperoleh melalui taubat dan rahmat Allah bukan semata melalui banyaknya ibadah, dan ibadah malam bukan satu-satunya ibadah yang menghasilkan ampunan karena seluruh amal saleh dapat menghapus kesalahan sebagaimana Q.S. Hud [11]: 114.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam menjaga persatuan',text:'Perilaku meneladani kesungguhan para sahabat dalam menjaga persatuan yang paling tepat adalah ...',options:['tidak terlibat dalam perselisihan agar tidak berpihak kepada salah satu pihak','mendahulukan kepentingan bersama dan mendamaikan yang berselisih','mendukung teman yang paling dekat dengannya dalam setiap perselisihan karena kesetiaan kepada teman merupakan keutamaan','memutus hubungan dengan teman yang berbeda pendapat agar tidak terjadi perselisihan yang lebih besar'],answer:1,explanation:'Q.S. Ali Imran [3]: 103 memerintahkan berpegang teguh kepada tali Allah seluruhnya dan melarang berpecah belah serta mengingatkan nikmat Allah yang mempersatukan hati sehingga menjadi bersaudara. Q.S. al-Hujurat [49]: 10 menyebut bahwa orang beriman itu bersaudara sehingga hendaklah mendamaikan antara kedua saudaramu. Q.S. asy-Syura [42]: 38 menyebut bahwa urusan diselesaikan dengan musyawarah. Hadis juga menyebut bahwa hadiah dapat menumbuhkan kasih sayang dan menghilangkan permusuhan. Hadis melarang memutuskan hubungan dengan sesama muslim lebih dari tiga hari. Hadis juga menyebut bahwa cukuplah seseorang dianggap berdusta apabila menyampaikan setiap yang didengarnya, sehingga menyebarkan kabar yang dapat menimbulkan perpecahan bukan perilaku yang diajarkan. Q.S. al-Maidah [5]: 8 memerintahkan berlaku adil dan melarang kebencian mendorong berlaku tidak adil, sehingga mendamaikan harus dilakukan tanpa memihak. Adapun mendukung teman yang paling dekat dalam setiap perselisihan tanpa mempertimbangkan kebenaran bukan kesetiaan yang benar karena kesetiaan yang benar adalah menolong teman dalam kebenaran dan mencegahnya dari kezaliman.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya keutamaan sahabat dalam Al-Quran dan hadis',text:'Keutamaan para sahabat disebut dalam Al-Quran dan hadis dengan berbagai gambaran. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya agar umat mengetahui bahwa sahabat lebih utama dari seluruh manusia setelah para nabi sehingga tidak ada yang menyamai mereka','hikmahnya agar umat mengetahui nama-nama sahabat dan peristiwa yang mereka alami','umat memiliki teladan nyata dari manusia biasa yang dapat ditiru','hikmahnya karena penyebutan keutamaan sahabat merupakan satu-satunya cara menjaga keutuhan ajaran Islam'],answer:2,explanation:'Q.S. at-Taubah [9]: 100 menyebut keridhaan Allah kepada Muhajirin dan Ansar serta orang yang mengikuti mereka dengan baik. Q.S. al-Fath [48]: 29 menggambarkan para sahabat bersama Rasulullah bersikap keras terhadap orang kafir dan berkasih sayang sesama mereka serta menyebut janji ampunan dan pahala yang besar bagi yang beriman dan beramal saleh di antara mereka. Q.S. al-Hasyr [59]: 8-9 menggambarkan keadaan Muhajirin yang diusir dari kampung halaman dan hartanya serta keadaan Ansar yang mengutamakan orang lain atas diri mereka. Hadis juga menyebut bahwa sebaik-baik manusia adalah generasiku kemudian yang sesudahnya kemudian yang sesudahnya. Hadis menyebut bahwa janganlah kalian mencela sahabatku. Hadis juga menganjurkan mengambil ajaran dari sumber yang terpercaya penyampaiannya. Adapun penyebutan keutamaan mereka bukan satu-satunya cara menjaga keutuhan ajaran karena Al-Quran sendiri dijaga oleh Allah sebagaimana Q.S. al-Hijr [15]: 9, dan keutamaan sahabat bertingkat-tingkat sehingga tidak dinyatakan bahwa seluruh mereka lebih utama dari seluruh manusia setelah para nabi tanpa perincian.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam menjaga salat berjamaah',text:'Kesungguhan para sahabat dalam menjaga salat berjamaah yang paling tepat adalah ...',options:['hadir di masjid hanya pada salat Subuh dan Isya karena keduanya paling berat bagi orang munafik','hadir setiap waktu salat dan tidak meninggalkan jamaah tanpa uzur','hadir di masjid pada setiap waktu salat walaupun dalam keadaan sakit sehingga harus dipapah oleh dua orang','tidak meninggalkan jamaah walaupun dalam keadaan sakit berat yang membahayakan apabila dipaksakan hadir'],answer:1,explanation:'Hadis menyebut bahwa salat yang paling berat bagi orang munafik adalah salat Isya dan salat Subuh dan seandainya mereka mengetahui keutamaannya maka mereka akan mendatanginya walaupun dengan merangkak. Sejarah juga mencatat sahabat yang buta bernama Ibn Ummi Maktum yang meminta keringanan kepada Rasulullah karena tidak ada yang menuntunnya ke masjid lalu Rasulullah bertanya apakah engkau mendengar azan, ia menjawab ya, lalu Rasulullah bersabda maka penuhilah panggilan itu, tetapi para ulama menjelaskan bahwa ketentuan itu berlaku bagi yang mampu dan tidak membahayakan dirinya. Hadis juga menyebut bahwa seandainya manusia mengetahui keutamaan azan dan saf pertama lalu tidak memperolehnya kecuali dengan undian maka mereka akan berundi untuk memperolehnya. Hadis menyebut bahwa barangsiapa berwudu dengan sempurna lalu keluar menuju salat maka ia berada di jalan Allah hingga kembali. Hadis juga melarang meninggikan suara di dalam masjid. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya, sehingga meninggalkan jamaah dibolehkan ketika terdapat uzur yang membahayakan.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan sahabat dalam beramal sembunyi-sembunyi',text:'Sebagian sahabat beramal secara sembunyi-sembunyi sehingga amalnya baru diketahui setelah mereka wafat. Analisis yang paling tepat terhadap hikmah kesungguhan tersebut adalah ...',options:['hikmahnya agar amal mereka tidak diketahui oleh orang lain sehingga terhindar dari pujian','amal tersembunyi lebih terjaga dari riya sehingga nilainya lebih tinggi','hikmahnya karena amal yang diketahui orang lain tidak diterima oleh Allah sehingga harus disembunyikan','hikmahnya agar amal mereka tidak ditiru oleh orang lain sehingga keutamaannya tetap milik mereka'],answer:1,explanation:'Hadis menyebut bahwa tujuh golongan dinaungi Allah pada hari yang tidak ada naungan kecuali naungan-Nya di antaranya orang yang bersedekah lalu menyembunyikannya sehingga tangan kirinya tidak mengetahui apa yang diinfakkan tangan kanannya. Hadis qudsi juga menyebut bahwa Allah Maha Cukup dari sekutu sehingga amal yang dikerjakan untuk Allah dan untuk selain-Nya ditolak. Sejarah mencatat Zainal Abidin dari kalangan keturunan sahabat yang memikul karung makanan pada malam hari untuk diberikan kepada keluarga miskin di Madinah dan keadaan itu baru diketahui setelah ia wafat karena keluarga yang biasa menerima bantuan tidak lagi memperolehnya. Q.S. al-Baqarah [2]: 271 menyebut bahwa menampakkan sedekah merupakan hal yang baik dan menyembunyikannya serta memberikannya kepada orang miskin lebih baik bagi mereka. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Adapun amal yang diketahui orang lain tetap diterima apabila niatnya benar, dan menampakkan amal dapat menjadi teladan bagi orang lain sehingga tidak selalu harus disembunyikan.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam menghadapi ujian',text:'Perilaku meneladani kesungguhan para sahabat dalam menghadapi ujian yang paling tepat bagi seorang pelajar adalah ...',options:['berhenti belajar sementara waktu hingga kesulitannya teratasi karena belajar dalam kesulitan tidak menghasilkan','tetap beribadah dan belajar walaupun sedang menghadapi kesulitan','menerima ujian dengan pasrah karena ujian merupakan ketentuan yang tidak dapat diubah','menyampaikan keadaannya kepada seluruh teman agar mereka membantu sehingga kesulitannya berkurang'],answer:1,explanation:'Q.S. al-Ankabut [29]: 2-3 menyebut bahwa manusia diuji agar diketahui siapa yang benar dan siapa yang dusta. Q.S. al-Baqarah [2]: 155-157 menyebut ujian dengan ketakutan, kelaparan, kekurangan harta, jiwa, dan buah-buahan serta memberi kabar gembira kepada orang yang sabar. Q.S. al-Hasyr [59]: 8 menggambarkan Muhajirin yang diusir dari kampung halaman dan hartanya karena mencari karunia Allah dan keridhaan-Nya serta menolong Allah dan Rasul-Nya. Hadis juga menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian orang yang saleh kemudian yang berikutnya. Hadis melarang mengeluh kepada manusia dan menyebut bahwa orang yang mengadukan kesedihannya kepada manusia tidak tergolong orang yang sabar, tetapi mengadukan kepada pihak yang dapat membantu merupakan sarana memperoleh pertolongan yang dianjurkan. Q.S. Yusuf [12]: 86 menggambarkan mengadukan kesusahan kepada Allah. Hadis juga menyebut bahwa barangsiapa menipu maka ia bukan dari golongan Rasulullah, sehingga berbuat curang dalam ujian bukan pilihan walaupun keadaan sulit.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sahabat sebagai perantara sampainya ajaran',text:'Seluruh ajaran Islam sampai kepada umat melalui perantaraan para sahabat. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['kedudukan itu berarti seluruh sahabat memiliki tingkat keilmuan yang sama sehingga riwayat mereka memiliki kekuatan yang sama','mereka perantara terpercaya sehingga riwayatnya menjadi dasar hukum','kedudukan itu berarti para sahabat merupakan sumber ajaran sehingga pendapat mereka setara dengan Al-Quran dan sunah','kedudukan itu berarti umat tidak perlu memeriksa riwayat karena seluruh sahabat dipastikan jujur dalam penyampaiannya'],answer:1,explanation:'Q.S. al-Maidah [5]: 67 memerintahkan Rasulullah menyampaikan apa yang diturunkan kepadanya dari Tuhannya, dan penyampaian itu sampai kepada umat melalui para sahabat. Hadis juga menyebut bahwa hendaklah orang yang hadir menyampaikan kepada orang yang tidak hadir. Hadis menyebut bahwa para sahabat merupakan bintang sehingga apabila bintang itu hilang maka sebagian besar yang dijanjikan kepada agama akan hilang. Q.S. an-Nisa [4]: 59 memerintahkan taat kepada Allah, Rasul, dan ulil amri serta mengembalikan perbedaan pendapat kepada Allah dan Rasul, sehingga pendapat pribadi sahabat dinilai berdasarkan kesesuaiannya dengan Al-Quran dan sunah. Hadis juga menyebut bahwa ulama merupakan pewaris para nabi, sehingga ilmu sampai melalui rangkaian penyampaian yang terpercaya. Ilmu hadis kemudian berkembang untuk memeriksa keadaan perawi termasuk sahabat dan generasi sesudahnya, sehingga pemeriksaan riwayat merupakan bagian dari menjaga ajaran bukan bentuk keraguan terhadap kejujuran sahabat.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam berdakwah',text:'Kesungguhan para sahabat dalam berdakwah yang paling tepat adalah ...',options:['berdakwah kepada seluruh masyarakat tanpa mempertimbangkan keadaan dan kemampuan penerima','berdakwah dengan cara yang tegas kepada seluruh orang agar mereka segera menerima ajaran','berdakwah dengan hikmah dan mendahulukan teladan dalam perbuatan','berdakwah hanya kepada pihak yang menunjukkan minat agar usahanya tidak sia-sia'],answer:2,explanation:'Q.S. an-Nahl [16]: 125 memerintahkan menyeru kepada jalan Tuhan dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Q.S. Ibrahim [14]: 4 menyebut bahwa Allah tidak mengutus seorang rasul melainkan dengan bahasa kaumnya agar ia dapat memberi penjelasan kepada mereka, yang menjadi dasar menyesuaikan cara dengan keadaan penerima. Sejarah mencatat para sahabat menyebar ke berbagai daerah setelah Rasulullah wafat untuk menyampaikan ajaran dan menghadapi kesulitan perjalanan serta penolakan. Q.S. asy-Syuara [26]: 109 menggambarkan nabi yang berkata aku tidak meminta imbalan kepadamu atas seruan itu karena imbalanku hanyalah dari Tuhan seluruh alam. Hadis juga menyebut bahwa sampaikanlah dariku walaupun satu ayat. Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga kesabaran ketika dakwah ditolak merupakan bagian dari kesungguhan. Q.S. Fushshilat [41]: 34-35 menganjurkan menolak kejahatan dengan cara yang lebih baik.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan ibadah para sahabat yang berbeda-beda bentuknya',text:'Kesungguhan ibadah para sahabat berbeda-beda bentuknya yaitu ada yang menonjol dalam sedekah, ada yang menonjol dalam ilmu, dan ada yang menonjol dalam keberanian. Analisis yang paling tepat terhadap hikmah perbedaan tersebut adalah ...',options:['hikmahnya agar setiap sahabat memperoleh kedudukan yang berbeda di sisi Allah','kesungguhan tidak terbatas satu bentuk sehingga tiap orang menemukan bidang','hikmahnya karena kemampuan sahabat berbeda-beda sehingga masing-masing melakukan apa yang mampu dilakukannya tanpa pilihan','hikmahnya agar sahabat tidak bersaing satu sama lain karena setiap mereka memiliki bidang yang berbeda'],answer:1,explanation:'Hadis menyebut bahwa Allah membagi akhlak sebagaimana membagi rezeki. Hadis juga menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia, sehingga kontribusi yang berbeda-beda seluruhnya bernilai apabila bermanfaat. Q.S. al-Baqarah [2]: 148 berbunyi dan bagi setiap umat ada kiblat yang ia menghadap kepadanya maka berlomba-lombalah dalam kebaikan. Q.S. an-Nahl [16]: 125 menunjukkan perbedaan cara dalam menyeru sesuai keadaan penerima. Hadis juga menyebut bahwa orang yang paling dicintai Allah adalah yang paling bermanfaat bagi manusia dan amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Sejarah mencatat Abu Bakar menonjol dalam keimanan dan sedekah, Umar dalam ketegasan dan keadilan, Utsman dalam kedermawanan dan rasa malu, dan Ali dalam ilmu dan keberanian, sehingga setiap umat dapat menemukan teladan yang sesuai dengan kecenderungannya. Adapun kedudukan di sisi Allah ditentukan oleh ketakwaan dan keikhlasan bukan oleh bentuk ibadah yang dipilih.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam menjaga waktu',text:'Perilaku meneladani kesungguhan para sahabat dalam menjaga waktu yang paling tepat bagi seorang pelajar adalah ...',options:['mengisi waktu dengan kegiatan yang menyenangkan walaupun tidak bermanfaat karena waktu merupakan kesempatan untuk bersenang-senang','membagi waktu teratur dan tidak menunda pekerjaan yang dapat diselesaikan','mengisi seluruh waktu dengan belajar agar tidak ada waktu yang terbuang','belajar hanya ketika menghadapi ujian agar waktu lain dapat digunakan untuk kegiatan lain'],answer:1,explanation:'Hadis menyebut bahwa dua nikmat yang banyak manusia tertipu di dalamnya yaitu kesehatan dan waktu luang. Hadis juga menyebut bahwa tidak akan bergeser kedua kaki seorang hamba pada hari kiamat hingga ditanya tentang empat perkara di antaranya tentang umurnya untuk apa dihabiskan dan tentang masa mudanya untuk apa digunakan. Hadis menyebut bahwa amal yang paling dicintai Allah adalah salat pada waktunya. Hadis juga menyebut bahwa termasuk kebaikan Islam seseorang adalah meninggalkan apa yang tidak bermanfaat baginya. Q.S. al-Asr [103]: 1-3 menyebut waktu sebagai dasar kerugian manusia apabila tidak digunakan untuk beriman, beramal saleh, saling menasihati dalam kebenaran, dan saling menasihati dalam kesabaran. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga keteraturan yang berkelanjutan lebih utama daripada usaha sesaat. Hadis juga menyebut bahwa tubuhmu memiliki hak atas dirimu sehingga mengisi seluruh waktu dengan belajar tanpa istirahat bukan cara yang diajarkan.'},
{level:'HOTS',indicator:'Menganalisis pengaruh kisah sahabat terhadap pembentukan akhlak pelajar',text:'Kisah kesungguhan ibadah para sahabat dipelajari dalam materi Akidah Akhlak. Analisis yang paling tepat terhadap pengaruh pembelajaran kisah tersebut bagi pembentukan akhlak pelajar adalah ...',options:['pengaruhnya bahwa pelajar memperoleh pengetahuan sejarah yang berguna dalam pelajaran lain','kisah memberi teladan nyata sehingga nilai tidak lagi bersifat abstrak','pengaruhnya bahwa pelajar memperoleh motivasi untuk menjadi pemimpin karena para sahabat menjadi pemimpin umat setelah Rasulullah','pengaruhnya bahwa pelajar dapat mengukur tingkat kesungguhannya dengan membandingkan dengan kesungguhan para sahabat sehingga merasa rendah diri'],answer:1,explanation:'Q.S. al-Hasyr [59]: 10 mengajarkan doa bagi orang beriman yang datang sesudah generasi sahabat agar tidak terdapat kedengkian dalam hati terhadap orang beriman, yang menunjukkan bahwa hubungan umat dengan sahabat merupakan hubungan cinta dan penghargaan. Hadis juga menyebut bahwa janganlah kalian mencela sahabatku. Hadis menyebut bahwa perumpamaan teman yang baik seperti penjual minyak wangi, yang menunjukkan pengaruh teladan terhadap pembentukan akhlak. Q.S. al-Ahzab [33]: 21 menyebut bahwa pada diri Rasulullah terdapat teladan yang baik, dan para sahabat merupakan pihak yang paling meneladani beliau sehingga kisah mereka menjadi teladan tingkat berikutnya. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis menganjurkan tidak merasa rendah diri dan menyebut bahwa sombong adalah menolak kebenaran dan meremehkan manusia, sehingga membandingkan diri dengan para sahabat seharusnya menghasilkan motivasi bukan perasaan rendah diri yang melumpuhkan.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam menjaga lisan',text:'Kesungguhan para sahabat dalam menjaga lisan yang paling tepat adalah ...',options:['berbicara yang baik atau diam dan tidak menyampaikan berita tanpa diperiksa','berbicara dengan bahasa yang halus walaupun isinya merendahkan orang lain agar tidak terasa kasar','tidak berbicara sama sekali kecuali untuk keperluan yang penting','menyampaikan seluruh hal yang didengarnya agar orang lain memperoleh informasi yang lengkap'],answer:0,explanation:'Hadis menyebut bahwa barangsiapa beriman kepada Allah dan hari akhir hendaklah berkata baik atau diam. Hadis juga menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya. Hadis melarang bersumpah dalam jual beli dan menyebut bahwa sumpah melariskan dagangan tetapi menghapus keberkahannya. Hadis juga menyebut bahwa celakalah orang yang berbicara lalu berdusta untuk membuat orang tertawa, celakalah ia, celakalah ia. Hadis menyebut bahwa cukuplah seseorang dianggap berdusta apabila menyampaikan setiap yang didengarnya. Q.S. al-Hujurat [49]: 12 melarang ghibah dan mencari-cari kesalahan orang lain. Q.S. Qaf [50]: 18 menyebut bahwa tidak ada satu ucapan pun yang diucapkan melainkan ada di sisinya malaikat pengawas yang selalu hadir. Adapun berbicara dengan bahasa halus tetapi merendahkan tetap merupakan pelanggaran karena yang dinilai adalah isinya, dan tidak berbicara sama sekali bukan kesungguhan menjaga lisan melainkan bentuk meninggalkan kewajiban menyampaikan kebaikan.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan sahabat dalam bermusyawarah',text:'Para sahabat bermusyawarah dalam memutuskan perkara yang tidak terdapat ketentuan tegasnya. Analisis yang paling tepat terhadap hikmah kesungguhan mereka dalam bermusyawarah adalah ...',options:['musyawarah menghasilkan keputusan yang lebih tepat dan lebih diterima','hikmahnya agar tidak ada pihak yang merasa ditinggalkan dalam pengambilan keputusan','hikmahnya agar keputusan yang diambil tidak disesali oleh pihak yang memutuskan','hikmahnya karena musyawarah merupakan syarat sah keputusan sehingga keputusan tanpa musyawarah tidak berlaku'],answer:0,explanation:'Q.S. asy-Syura [42]: 38 menyebut bahwa urusan orang beriman diselesaikan dengan musyawarah di antara mereka. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah dalam urusan kemudian apabila telah membulatkan tekad maka bertawakallah kepada Allah. Hadis juga menyebut bahwa orang yang bermusyawarah tidak akan menyesal dan orang yang beristikharah tidak akan kecewa. Sejarah mencatat Abu Bakar bermusyawarah dengan para sahabat dalam persoalan memerangi pihak yang menolak menunaikan zakat dan dalam pengumpulan Al-Quran, dan Umar bermusyawarah dalam persoalan pembagian tanah taklukan serta penetapan tahun hijriah. Hadis juga menganjurkan meminta nasihat dan menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya. Q.S. an-Nisa [4]: 83 menyebut bahwa apabila datang kepada mereka suatu berita tentang keamanan atau ketakutan mereka menyebarkannya padahal apabila mengembalikannya kepada Rasul dan ulil amri maka orang yang menyelidikinya akan mengetahui kebenarannya. Adapun musyawarah bukan syarat sah keputusan secara mutlak karena terdapat keputusan yang dapat diambil oleh pemimpin setelah mempertimbangkan keadaan.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam beramal setelah mengetahui keutamaannya',text:'Perilaku meneladani para sahabat yang bersegera beramal setelah mengetahui keutamaannya adalah ...',options:['melaksanakan amal yang diketahui keutamaannya sesegera mungkin tanpa mempertimbangkan kemampuan','menunda pelaksanaan amal hingga mampu melaksanakannya dengan sempurna agar hasilnya maksimal','melaksanakan amal yang diketahui keutamaannya tanpa menunda','melaksanakan seluruh amal yang diketahui keutamaannya sekaligus agar memperoleh seluruh keutamaannya'],answer:2,explanation:'Q.S. al-Muminun [23]: 61 menyebut bahwa mereka bersegera dalam kebaikan dan mereka adalah orang-orang yang lebih dahulu memperolehnya. Q.S. Ali Imran [3]: 133 memerintahkan bersegera kepada ampunan dari Tuhan dan surga yang luasnya seluas langit dan bumi. Hadis juga menyebut bahwa bersegeralah dalam beramal sebelum datang tujuh perkara. Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa beramallah sesuai kemampuan kalian karena Allah tidak jemu sehingga kalian jemu. Hadis menyebut bahwa apabila seseorang mengerjakan suatu amal maka hendaklah mengerjakannya dengan itqan. Hadis juga menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya. Adapun menunda hingga mampu melaksanakan dengan sempurna sering berakibat amal tidak terlaksana sama sekali karena kesempurnaan yang dimaksud tidak tercapai, sehingga memulai dengan kadar yang mampu lalu meningkatkannya secara bertahap merupakan cara yang diajarkan.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sahabat yang berbeda tingkat keutamaannya',text:'Para sahabat memiliki tingkat keutamaan yang berbeda seperti yang lebih dahulu masuk Islam lebih utama dari yang kemudian. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['seluruh sahabat berhak atas cinta walaupun tingkat keutamaannya berbeda','kedudukan itu berarti sahabat yang lebih rendah tingkatnya tidak layak menjadi teladan bagi umat','kedudukan itu berarti umat wajib mengikuti pendapat sahabat yang lebih utama dalam seluruh persoalan walaupun terdapat dalil yang berbeda','kedudukan itu berarti sahabat yang lebih utama tidak pernah melakukan kekeliruan'],answer:0,explanation:'Q.S. al-Hadid [57]: 10 berbunyi dan mengapa kamu tidak menafkahkan hartamu di jalan Allah padahal milik Allah seluruh warisan langit dan bumi, tidak sama di antara kamu orang yang berinfak sebelum penaklukan Makkah dan berperang, mereka lebih besar derajatnya daripada orang yang berinfak sesudahnya dan berperang, dan kepada masing-masing Allah telah menjanjikan kebaikan. Q.S. at-Taubah [9]: 100 menyebut Muhajirin dan Ansar serta orang yang mengikuti mereka dengan baik. Hadis juga menyebut bahwa janganlah kalian mencela sahabatku karena seandainya salah seorang dari kalian menginfakkan emas sebesar gunung Uhud maka tidak akan menyamai satu mud infak salah seorang dari mereka dan tidak pula separuhnya. Hadis menyebut bahwa sebaik-baik manusia adalah generasiku kemudian yang sesudahnya kemudian yang sesudahnya. Hadis juga melarang berlebihan dalam memuji dan menyebut bahwa Rasulullah bersabda janganlah kalian berlebih-lebihan dalam memujiku sebagaimana orang Nasrani berlebihan dalam memuji Isa bin Maryam. Adapun mengikuti pendapat sahabat dilakukan dengan mempertimbangkan dalil yang menjadi dasarnya karena yang wajib diikuti adalah Al-Quran dan sunah, dan sahabat yang tingkatnya lebih rendah tetap merupakan teladan dalam kesungguhan beramal.'},
{level:'HOTS',indicator:'Menentukan kesungguhan ibadah Abu Dzar dan sahabat ahli zuhud',text:'Kesungguhan ibadah para sahabat yang memilih hidup zuhud yang paling tepat adalah ...',options:['meninggalkan seluruh harta dunia karena dunia merupakan tempat yang tidak bernilai','hati tidak terikat harta walaupun hartanya ada di tangan','memakai pakaian yang paling sederhana dan memakan makanan yang paling murah agar terasa berat sehingga pahalanya lebih besar','tidak menerima jabatan apa pun karena jabatan selalu mengalihkan dari ibadah'],answer:1,explanation:'Hadis menyebut bahwa zuhud terhadap dunia bukan berarti mengharamkan yang halal dan bukan berarti menyia-nyiakan harta, tetapi zuhud adalah engkau lebih meyakini apa yang di tangan Allah daripada apa yang di tanganmu. Hadis juga menyebut bahwa dunia bagi Rasulullah hanya seperti pengendara yang berteduh di bawah pohon lalu pergi meninggalkannya. Hadis menyebut kisah Abu Dzar yang menolak jabatan dan menyampaikan bahwa dirinya merasa tidak mampu memikul tanggung jawabnya. Hadis juga menyebut bahwa sebaik-baik harta adalah harta yang berada di tangan orang saleh. Hadis menganjurkan bekerja dan menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah. Q.S. al-Araf [7]: 32 menyebut siapakah yang mengharamkan perhiasan Allah yang telah dikeluarkan untuk hamba-hamba-Nya dan rezeki yang baik-baik. Hadis juga melarang membebani diri dan menyebut bahwa beramallah sesuai kemampuan kalian. Adapun meninggalkan seluruh harta bukan zuhud yang diajarkan karena memiliki harta yang halal dibolehkan apabila hati tidak terikat kepadanya.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan Abdurrahman bin Auf dalam memadukan kekayaan dan ketakwaan',text:'Abdurrahman bin Auf merupakan sahabat yang kaya tetapi termasuk sepuluh orang yang dijamin surga. Analisis yang paling tepat terhadap kesungguhan beliau adalah ...',options:['kekayaan dan ketakwaan dapat berada bersama bila hartanya halal','kesungguhan beliau berupa keberaniannya berdagang di pasar Madinah yang dikuasai oleh pedagang Yahudi','kesungguhan beliau berupa kesediaannya meninggalkan harta ketika hijrah lalu membangun usaha kembali dari awal dengan cara yang halal','kesungguhan beliau berupa kesediaannya menerima seluruh harta yang ditawarkan sahabat lain sehingga usahanya cepat berkembang'],answer:0,explanation:'Sejarah mencatat Abdurrahman bin Auf tiba di Madinah tanpa harta karena meninggalkannya di Makkah, lalu Sa ad bin Rabi menawarkan separuh hartanya dan salah seorang istrinya tetapi Abdurrahman menolak dengan sopan dan hanya meminta ditunjukkan arah pasar, kemudian memulai usaha dengan berdagang keju dan minyak samin hingga berkembang. Hadis juga menyebut bahwa sepuluh orang dijamin surga dan Abdurrahman bin Auf termasuk di antaranya. Q.S. an-Nur [24]: 37 menggambarkan orang yang tidak dilalaikan oleh perniagaan dan jual beli dari mengingat Allah dan mendirikan salat serta menunaikan zakat. Hadis juga menyebut bahwa sebaik-baik harta adalah harta yang berada di tangan orang saleh. Q.S. al-Hadid [57]: 10 menyebut perbedaan derajat antara orang yang berinfak sebelum penaklukan Makkah dan sesudahnya. Hadis menganjurkan bersedekah dan menyebut bahwa sedekah tidak mengurangi harta. Adapun keberanian berdagang di pasar merupakan bagian dari kesungguhannya tetapi bukan inti kesungguhan ibadahnya, dan menerima harta dari sahabat lain bukan cara yang dipilihnya karena beliau memilih memulai dari usaha sendiri.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam menjaga salat tepat waktu',text:'Kesungguhan para sahabat dalam menjaga salat tepat waktu yang paling tepat adalah ...',options:['melaksanakan salat pada awal waktu dan menghentikan kegiatan ketika azan dikumandangkan','melaksanakan salat pada awal waktu saja dan tidak melaksanakan salat sunah karena yang penting adalah salat wajib','melaksanakan salat tepat waktu hanya ketika berada di masjid karena salat di tempat lain kurang utama','salat pada awal waktu dan menghentikan kegiatan ketika azan berkumandang'],answer:3,explanation:'Hadis menyebut bahwa amal yang paling dicintai Allah adalah salat pada waktunya. Q.S. an-Nur [24]: 37 menggambarkan orang yang tidak dilalaikan oleh perniagaan dan jual beli dari mengingat Allah dan mendirikan salat serta menunaikan zakat. Q.S. al-Jumuah [62]: 9 memerintahkan meninggalkan jual beli ketika azan Jumat dikumandangkan. Hadis juga menyebut bahwa orang yang paling buruk pencuriannya adalah yang mencuri dalam salatnya yaitu yang tidak menyempurnakan rukuk dan sujudnya. Q.S. al-Muminun [23]: 2 menyebut ciri orang beriman yang khusyuk dalam salatnya. Q.S. an-Nisa [4]: 103 menyebut bahwa salat merupakan kewajiban yang ditentukan waktunya atas orang beriman. Q.S. al-Baqarah [2]: 238 memerintahkan memelihara salat-salat terutama salat wusta. Hadis juga menyebut keringanan menjamak dan mengqasar dalam perjalanan serta tayamum ketika tidak memperoleh air, sehingga keadaan sulit bukan alasan meninggalkan salat. Adapun meninggalkan salat sunah seluruhnya bukan cara yang dianjurkan karena salat sunah menyempurnakan kekurangan salat wajib, dan salat tepat waktu tetap utama di mana pun dilaksanakan.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan para sahabat walaupun telah dijamin surga',text:'Sebagian sahabat dijamin masuk surga tetapi tetap bersungguh-sungguh dalam beribadah. Analisis yang paling tepat terhadap hikmah kesungguhan tersebut adalah ...',options:['jaminan surga menjadi alasan bersyukur dengan amal yang lebih banyak','hikmahnya agar umat mengetahui bahwa sahabat yang dijamin surga tetap beribadah sehingga umat tidak merasa cukup dengan amal yang sedikit','hikmahnya karena ibadah merupakan syarat tetap berlakunya jaminan surga sehingga tanpa ibadah jaminan itu batal','hikmahnya agar jaminan surga itu terbukti benar sehingga tidak diragukan oleh umat'],answer:0,explanation:'Hadis menyebut bahwa sepuluh orang dijamin surga dan menyebut nama-nama mereka termasuk Abu Bakar, Umar, Utsman, Ali, Abdurrahman bin Auf, dan yang lain. Hadis juga menyebut bahwa Rasulullah salat malam hingga kedua kakinya bengkak dan ketika ditanya mengapa beliau melakukan itu padahal dosa-dosanya telah diampuni beliau menjawab tidakkah aku ingin menjadi hamba yang bersyukur. Q.S. Ibrahim [14]: 7 menyebut bahwa apabila bersyukur maka Allah menambah nikmat. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis menyebut bahwa hati manusia berada di antara dua jari dari jari-jari ar-Rahman yang Dia bolak-balikkan sesuai kehendak-Nya, sehingga berhati-hati terhadap keadaan hati hingga akhir hayat merupakan sikap yang benar. Hadis juga menganjurkan memohon ketetapan hati dalam doa. Q.S. al-Hijr [15]: 99 memerintahkan menyembah Tuhan hingga datang keyakinan yaitu kematian, sehingga ibadah berkelanjutan hingga akhir hayat merupakan perintah. Adapun ibadah bukan syarat yang dapat membatalkan jaminan bagi yang telah dijamin, tetapi jaminan itu sendiri berkaitan dengan kesudahan hidup yang baik yang diketahui oleh Allah.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam beribadah ketika sedang sibuk',text:'Perilaku meneladani kesungguhan para sahabat dalam beribadah ketika sedang sibuk yang paling tepat bagi seorang pelajar adalah ...',options:['menghentikan kegiatan saat waktu salat dan mengatur jadwal belajar','melaksanakan ibadah sunah sebanyak mungkin dan meninggalkan kegiatan belajar karena ibadah lebih utama daripada belajar','melaksanakan ibadah dengan cepat agar segera kembali kepada kegiatan yang belum selesai','menunda ibadah hingga seluruh kegiatan selesai agar ibadah dapat dilaksanakan dengan tenang'],answer:0,explanation:'Hadis menyebut bahwa amal yang paling dicintai Allah adalah salat pada waktunya. Q.S. an-Nur [24]: 37 menggambarkan orang yang tidak dilalaikan oleh perniagaan dan jual beli dari mengingat Allah dan mendirikan salat. Q.S. al-Jumuah [62]: 9 memerintahkan meninggalkan jual beli ketika azan dikumandangkan. Hadis juga menyebut bahwa salat apabila telah didirikan maka tidak ada salat kecuali salat yang sedang didirikan. Hadis menganjurkan amal yang berkelanjutan walaupun sedikit sehingga membaca Al-Quran beberapa ayat secara teratur lebih utama daripada banyak tetapi terhenti. Hadis juga menyebut bahwa tidak menyempurnakan rukuk dan sujud merupakan pencurian dalam salat, sehingga melaksanakan dengan cepat agar segera kembali kepada kegiatan bukan cara yang diajarkan. Q.S. at-Taubah [9]: 122 menyebut bahwa tidak sepatutnya orang mukmin pergi seluruhnya untuk berperang melainkan hendaklah dari setiap golongan ada yang memperdalam pengetahuan agama, sehingga belajar merupakan kewajiban yang tidak ditinggalkan karena ibadah sunah.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan para sahabat dalam mengamalkan ayat yang baru diterima',text:'Para sahabat mempelajari sepuluh ayat lalu tidak berpindah kepada sepuluh ayat berikutnya hingga memahami dan mengamalkannya. Analisis yang paling tepat terhadap kesungguhan tersebut adalah ...',options:['tujuannya memahami dan mengamalkan bukan sekadar mengumpulkan hafalan','kesungguhan itu berarti umat sekarang tidak boleh menghafal Al-Quran dengan cepat karena cara sahabat lebih utama','kesungguhan itu menunjukkan bahwa sahabat tidak mampu menghafal lebih dari sepuluh ayat dalam satu waktu','kesungguhan itu menunjukkan bahwa mempelajari Al-Quran harus dilakukan secara lambat agar maknanya dipahami'],answer:0,explanation:'Riwayat menyebut bahwa kaum itu mempelajari sepuluh ayat dari Rasulullah lalu tidak berpindah kepada sepuluh ayat berikutnya hingga memahami apa yang terkandung di dalamnya dan mengamalkannya, sehingga mereka mempelajari ilmu dan amal bersama-sama. Q.S. Shad [38]: 29 menyebut bahwa Al-Quran merupakan kitab yang diturunkan agar diperhatikan ayat-ayatnya dan agar orang yang berakal mengambil pelajaran. Q.S. al-Jumuah [62]: 5 mengecam orang yang diberi tanggung jawab membawa Taurat lalu tidak membawanya seperti keledai yang membawa kitab-kitab yang tebal. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. al-Baqarah [2]: 121 menyebut bahwa orang yang diberi kitab lalu membacanya dengan bacaan yang sebenarnya merupakan orang yang beriman kepadanya. Hadis menganjurkan menghafal Al-Quran dan menyebut keutamaan penghafal Al-Quran, sehingga menghafal dengan cepat bukan perbuatan yang tercela apabila disertai pemahaman dan pengamalan. Adapun kemampuan menghafal para sahabat beragam dan terdapat sahabat yang menghafal seluruh Al-Quran pada masa Rasulullah.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam berinfak pada waktu sulit',text:'Kesungguhan para sahabat dalam berinfak pada waktu sulit yang paling tepat adalah ...',options:['memberi hanya ketika memperoleh harta yang banyak karena memberi dalam jumlah sedikit tidak bermanfaat bagi penerima','memberi kepada pihak yang paling memerlukan walaupun keluarga sendiri tidak memperoleh bagian yang cukup','memberi dari yang dimiliki walaupun sedikit pada waktu yang diperlukan','memberi seluruh harta yang dimiliki sehingga keluarganya memerlukan bantuan dari pihak lain'],answer:2,explanation:'Q.S. al-Baqarah [2]: 261 memberi perumpamaan orang yang menafkahkan hartanya di jalan Allah seperti satu biji yang menumbuhkan tujuh tangkai dan pada setiap tangkai terdapat seratus biji. Hadis juga menyebut bahwa lindungilah diri kalian dari api neraka walaupun dengan separuh butir kurma dan apabila tidak memiliki maka dengan kata yang baik. Hadis menyebut kisah Perang Tabuk ketika Umar membawa separuh hartanya, Abu Bakar membawa seluruh hartanya, Utsman memberi dalam jumlah besar, dan Abdurrahman bin Auf memberi dua ratus uqiyah, serta terdapat sahabat yang memberi satu sha kurma dan ada yang diolok-olok karena pemberiannya sedikit lalu turun ayat yang membela mereka. Q.S. at-Taubah [9]: 79 menggambarkan orang yang mencela pemberi sedekah secara sukarela dan yang mencela orang yang tidak memperoleh kecuali sedikit lalu Allah memperolok-olokkan mereka. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah dan mulailah dari orang yang menjadi tanggunganmu, sehingga keluarga tetap memperoleh haknya sebelum pihak lain. Q.S. al-Baqarah [2]: 264 melarang menyebut-nyebut pemberian dan menyakiti perasaan penerima.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan sahabat dalam menjaga amanah kepemimpinan',text:'Para sahabat yang diberi amanah kepemimpinan hidup sederhana dan berhati-hati terhadap harta umat. Analisis yang paling tepat terhadap hikmah kesungguhan tersebut adalah ...',options:['hikmahnya agar pemimpin tidak memerlukan pengawalan karena masyarakat mempercayainya','hikmahnya agar pemimpin tidak disangka menggunakan harta umat untuk kepentingan pribadi','hikmahnya karena kesederhanaan pemimpin merupakan syarat sah kepemimpinannya sehingga pemimpin yang hidup mewah tidak sah kekuasaannya','harta umat merupakan amanah sehingga pemimpin berhati-hati dan sederhana'],answer:3,explanation:'Sejarah mencatat Umar yang menetapkan bagian untuk dirinya dari baitul mal setara dengan bagian seorang dari kaum muslimin dan menolak memakai pakaian yang lebih baik ketika menerima utusan dari Persia. Sejarah juga mencatat Abu Bakar yang tetap berdagang setelah menjadi khalifah hingga para sahabat menetapkan gaji untuknya dari baitul mal karena perdagangannya mengganggu urusan umat, dan Abu Bakar mengembalikan sisa harta yang telah diterimanya ketika mendekati ajalnya. Hadis juga menyebut kisah seorang petugas pengumpul zakat bernama Ibn al-Lutbiyyah yang kembali membawa sebagian hadiah dan berkata ini untuk kalian dan ini dihadiahkan kepadaku, lalu Rasulullah bersabda di mimbar mengapa tidak duduk saja di rumah ayahnya dan melihat apakah ia diberi hadiah, yang menunjukkan kehati-hatian terhadap hadiah yang berkaitan dengan jabatan. Hadis menyebut bahwa setiap kalian adalah pemimpin dan akan dimintai pertanggungjawaban tentang yang dipimpinnya. Adapun kesederhanaan pemimpin bukan syarat sah kekuasaan melainkan tanda ketakwaan dan kehati-hatian.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani keberanian sahabat dalam menyatakan kebenaran',text:'Perilaku meneladani keberanian para sahabat dalam menyatakan kebenaran bagi seorang pelajar adalah ...',options:['tidak menyampaikan kebenaran apabila mayoritas teman memilih yang salah karena melawan mayoritas tidak akan berhasil','menyampaikan kebenaran dengan cara yang keras agar pihak yang melanggar segera menyadari kesalahannya','menyampaikan kebenaran sopan dan tidak berdiam saat melihat pelanggaran','menyampaikan kebenaran kepada siapa pun tanpa mempertimbangkan cara dan waktu'],answer:2,explanation:'Hadis menyebut bahwa jihad yang paling utama adalah menyampaikan kata yang benar di hadapan pemimpin yang zalim. Q.S. an-Nahl [16]: 125 memerintahkan menyeru kepada jalan Tuhan dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya dan tidaklah kekasaran ada pada sesuatu melainkan ia merusaknya. Hadis menyebut bahwa kejujuran membawa kepada kebaikan dan kebaikan membawa ke surga. Hadis juga menyebut bahwa barangsiapa melihat kemungkaran hendaklah mengubahnya dengan tangan, dengan lisan, atau dengan hati. Q.S. an-Nisa [4]: 135 memerintahkan menjadi saksi karena Allah walaupun terhadap diri sendiri dan kerabat. Hadis juga menganjurkan memastikan kebenaran sebelum menyampaikannya sebagaimana Q.S. al-Isra [17]: 36 yang melarang mengikuti sesuatu yang tidak diketahui. Adapun tidak menyampaikan kebenaran karena mayoritas memilih yang salah bukan keberanian yang diajarkan karena Q.S. al-Anam [6]: 116 memperingatkan bahwa menuruti kebanyakan orang di bumi dapat menyesatkan dari jalan Allah.'},
{level:'HOTS',indicator:'Menganalisis kesungguhan para sahabat dalam menjaga persaudaraan Muhajirin dan Ansar',text:'Kaum Ansar menyambut kaum Muhajirin dengan membagi harta dan rumah mereka. Analisis yang paling tepat terhadap kesungguhan tersebut adalah ...',options:['kesungguhan itu menunjukkan bahwa kaum Muhajirin berhak memperoleh harta kaum Ansar karena telah meninggalkan hartanya','kesungguhan itu berarti kaum Muhajirin tidak perlu bekerja karena keperluannya telah ditanggung oleh kaum Ansar','kesungguhan itu menunjukkan bahwa kaum Ansar lebih utama dari kaum Muhajirin karena mereka yang memberi','persaudaraan iman menghasilkan kesediaan berkorban dan saling mengutamakan'],answer:3,explanation:'Q.S. al-Hasyr [59]: 9 berbunyi dan orang-orang yang telah menempati kota Madinah dan telah beriman sebelum kedatangan mereka mencintai orang yang berhijrah kepada mereka dan tidak menaruh keinginan dalam hati mereka terhadap apa yang diberikan kepada mereka dan mengutamakan orang lain atas diri mereka sendiri walaupun diri mereka memerlukan, dan siapa yang dipelihara dari kekikiran maka mereka itulah orang yang beruntung. Q.S. al-Anfal [8]: 72-73 menyebut ikatan antara kaum mukmin yang berhijrah dan yang memberi tempat serta menolong. Hadis juga menyebut kisah Rasulullah yang mempersaudarakan antara kaum Muhajirin dan kaum Ansar di Madinah. Hadis menyebut bahwa tidak beriman seseorang hingga mencintai saudaranya sebagaimana mencintai dirinya sendiri. Sejarah mencatat Abdurrahman bin Auf yang menolak separuh harta saudaranya dari kaum Ansar dan hanya meminta ditunjukkan arah pasar, sehingga tidak bergantung dalam waktu yang lama. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah. Adapun keutamaan kaum Ansar dan kaum Muhajirin keduanya disebut dalam Al-Quran sehingga tidak dinyatakan salah satunya lebih utama secara mutlak.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam berzikir dan mengingat Allah',text:'Kesungguhan para sahabat dalam berzikir dan mengingat Allah yang paling tepat adalah ...',options:['berzikir sepanjang waktu tanpa melaksanakan kegiatan lain agar zikirnya tidak terputus','berzikir dengan suara yang keras bersama-sama agar terasa lebih khusyuk dan mendorong orang lain ikut berzikir','berzikir hanya pada waktu tertentu yang ditetapkan agar zikir menjadi teratur dan tidak mengganggu kegiatan','berzikir dalam berbagai keadaan dan disertai pemahaman maknanya'],answer:3,explanation:'Q.S. Ali Imran [3]: 191 menggambarkan orang yang mengingat Allah dalam keadaan berdiri, duduk, dan berbaring serta memikirkan penciptaan langit dan bumi. Q.S. al-Ahzab [33]: 41-42 memerintahkan berzikir kepada Allah dengan zikir yang sebanyak-banyaknya dan bertasbih pada waktu pagi dan petang. Hadis juga menyebut bahwa Rasulullah berzikir dalam seluruh keadaannya. Hadis menyebut bahwa perumpamaan orang yang mengingat Tuhannya dan orang yang tidak mengingat Tuhannya seperti orang yang hidup dan orang yang mati. Hadis juga menganjurkan zikir pada waktu tertentu seperti sesudah salat dan ketika bangun tidur. Q.S. al-Araf [7]: 55 memerintahkan berdoa dengan rendah diri dan suara yang lembut, dan hadis melarang meninggikan suara ketika dapat mengganggu orang yang sedang salat, sehingga zikir dengan suara keras bersama-sama bukan adab yang diajarkan secara umum. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesungguhan para sahabat walaupun jumlah mereka sedikit',text:'Para sahabat menghadapi musuh yang jumlahnya jauh lebih besar tetapi tetap teguh. Analisis yang paling tepat terhadap hikmah kesungguhan tersebut adalah ...',options:['hikmahnya agar umat tidak mengandalkan jumlah dalam menghadapi persoalan','kemenangan ditentukan iman dan ketaatan bukan oleh jumlah pasukan','hikmahnya karena musuh yang jumlahnya besar selalu kalah akibat sombong dengan jumlahnya sehingga tidak perlu persiapan yang sungguh-sungguh','hikmahnya agar umat mengetahui bahwa jumlah yang sedikit dapat menang apabila sungguh-sungguh'],answer:1,explanation:'Q.S. al-Baqarah [2]: 249 menceritakan pasukan Thalut yang diuji dengan sungai sehingga hanya sedikit yang menyeberang bersama orang beriman dan mereka berkata berapa banyak golongan yang sedikit dapat mengalahkan golongan yang banyak dengan izin Allah dan Allah bersama orang-orang yang sabar. Q.S. al-Anfal [8]: 9-10 menceritakan Perang Badar ketika kaum muslimin memohon pertolongan lalu Allah mengabulkan dengan menurunkan seribu malaikat yang datang berturut-turut. Q.S. at-Taubah [9]: 25-26 menceritakan Perang Hunain ketika jumlah yang banyak tidak bermanfaat dan sebagian besar pasukan mundur. Q.S. al-Anfal [8]: 60 memerintahkan mempersiapkan kekuatan dan kuda yang ditambat untuk menghadapi musuh. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah lalu bertawakal setelah membulatkan tekad, sehingga ketaatan kepada pimpinan merupakan bagian dari kesungguhan. Hadis juga menyebut bahwa pertolongan itu bersama kesabaran. Adapun persiapan tetap diperlukan walaupun musuh sombong dengan jumlahnya karena Q.S. al-Anfal [8]: 60 memerintahkan mempersiapkan kekuatan.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam menjaga lisan dan hati',text:'Perilaku meneladani kesungguhan para sahabat dalam menjaga lisan dan hati adalah ...',options:['tidak menilai perbuatan orang lain karena menilai merupakan hak Allah','menjaga lisan dari gunjingan dan hati dari hasad serta riya','menyampaikan perasaan tersakiti kepada teman lain agar memperoleh dukungan sebelum menyampaikannya kepada pihak yang bersangkutan','tidak membicarakan orang lain sama sekali agar terhindar dari ghibah'],answer:1,explanation:'Hadis menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya. Hadis juga menyebut bahwa dalam tubuh terdapat segumpal daging yang apabila baik maka baiklah seluruh tubuh dan apabila rusak maka rusaklah seluruh tubuh yaitu hati. Hadis menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian. Hadis juga melarang hasad dan menyebut bahwa hasad memakan kebaikan sebagaimana api memakan kayu bakar. Q.S. al-Hujurat [49]: 12 melarang berprasangka buruk, mencari-cari kesalahan, dan ghibah. Hadis juga menganjurkan menyelesaikan persoalan secara langsung dan menyebut bahwa tidak halal bagi seorang muslim mendiamkan saudaranya lebih dari tiga hari serta yang terbaik di antara keduanya adalah yang memulai salam. Hadis menganjurkan istighfar dan menyebut bahwa barangsiapa memperbanyak istighfar maka Allah memberi jalan keluar dari setiap kesedihan dan rezeki dari arah yang tidak disangka. Adapun menyampaikan perasaan tersakiti kepada teman lain sebelum menyampaikannya kepada pihak yang bersangkutan dapat menjadi bentuk ghibah dan memperluas persoalan.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sahabat Ansar dalam keutamaan umat',text:'Kaum Ansar memperoleh keutamaan khusus karena memberi tempat dan menolong kaum Muhajirin. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['kedudukan itu berarti kaum Ansar lebih utama dari seluruh sahabat karena mereka yang menolong','kedudukan itu berarti kaum Muhajirin tidak memperoleh keutamaan karena mereka yang menerima bantuan','keutamaan Ansar karena berkorban dan mendahulukan saudara seimannya','kedudukan itu berarti umat Islam wajib mengikuti pendapat kaum Ansar dalam seluruh persoalan agama'],answer:2,explanation:'Q.S. al-Hasyr [59]: 9 menggambarkan keutamaan kaum Ansar yang mengutamakan orang lain atas diri mereka sendiri walaupun diri mereka memerlukan. Q.S. al-Anfal [8]: 72 menyebut orang yang beriman dan berhijrah serta berjihad dengan harta dan jiwanya di jalan Allah dan orang yang memberi tempat dan menolong sebagai orang yang benar-benar beriman dan memperoleh ampunan dan rezeki yang mulia. Q.S. at-Taubah [9]: 100 menyebut keridhaan Allah kepada Muhajirin dan Ansar serta orang yang mengikuti mereka dengan baik, sehingga kedua golongan disebut bersama. Hadis juga menyebut bahwa tanda iman adalah mencintai kaum Ansar dan tanda nifaq adalah membenci kaum Ansar. Hadis menyebut bahwa Allah memilih para sahabat bagi Nabi-Nya. Q.S. al-Fath [48]: 29 menggambarkan para sahabat bersama Rasulullah bersikap keras terhadap orang kafir dan berkasih sayang sesama mereka. Adapun mengikuti pendapat kaum Ansar atau Muhajirin dilakukan dengan mempertimbangkan dalil yang menjadi dasarnya karena yang wajib diikuti adalah Al-Quran dan sunah.'},
{level:'HOTS',indicator:'Menentukan kesungguhan para sahabat dalam menjaga akhlak terhadap Rasulullah',text:'Kesungguhan para sahabat dalam menjaga akhlak terhadap Rasulullah yang paling tepat adalah ...',options:['tidak bertanya kepada Rasulullah agar tidak mengganggu beliau karena pertanyaan menunjukkan kurangnya pemahaman','tidak berbicara di hadapan Rasulullah sama sekali karena berbicara merupakan bentuk tidak hormat','merendahkan suara, tidak mendahului, dan melaksanakan perintah segera','melaksanakan perintah Rasulullah setelah mempertimbangkan keadaannya karena yang penting adalah niat yang baik'],answer:2,explanation:'Q.S. al-Hujurat [49]: 1 melarang mendahului Allah dan Rasul-Nya dan memerintahkan bertakwa kepada Allah. Q.S. al-Hujurat [49]: 2 melarang meninggikan suara di atas suara Nabi dan melarang memanggil beliau dengan suara keras sebagaimana memanggil sebagian terhadap sebagian yang lain. Q.S. al-Hujurat [49]: 3 memuji orang yang merendahkan suaranya di sisi Rasulullah dan menyebut bahwa mereka merupakan orang yang diuji hatinya untuk bertakwa. Q.S. an-Nur [24]: 63 melarang menjadikan panggilan Rasul di antara mereka seperti panggilan sebagian terhadap sebagian yang lain. Q.S. al-Ahzab [33]: 53 menyebut adab tidak memasuki rumah Nabi tanpa izin dan tidak berlama-lama setelah makan. Hadis juga menyebut bahwa Rasulullah tidak menyukai orang berdiri untuk menghormatinya. Q.S. an-Nisa [4]: 59 memerintahkan taat kepada Allah dan Rasul. Hadis menganjurkan bertanya ketika belum memahami sebagaimana para sahabat bertanya tentang hal yang belum mereka ketahui dan Rasulullah menjawabnya.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya sahabat sebagai generasi terbaik',text:'Generasi sahabat disebut sebagai generasi terbaik. Analisis yang paling tepat terhadap hikmah sebutan tersebut bagi umat yang datang kemudian adalah ...',options:['hikmahnya agar umat mengetahui bahwa tidak ada generasi yang dapat menyamai generasi sahabat','hikmahnya agar umat tidak berusaha mencapai tingkat kesungguhan generasi sahabat karena tingkat itu tidak mungkin dicapai','hikmahnya karena generasi sahabat memperoleh keistimewaan yang tidak diberikan kepada generasi lain sehingga amal generasi lain tidak bernilai','umat memiliki ukuran masyarakat yang menerapkan ajaran secara benar'],answer:3,explanation:'Hadis menyebut bahwa sebaik-baik manusia adalah generasiku kemudian yang sesudahnya kemudian yang sesudahnya. Q.S. at-Taubah [9]: 100 menyebut keridhaan Allah kepada Muhajirin dan Ansar serta orang yang mengikuti mereka dengan baik, sehingga mengikuti mereka dengan baik merupakan jalan memperoleh keridhaan yang sama. Hadis juga menyebut bahwa janganlah kalian mencela sahabatku. Hadis menyebut bahwa para sahabat merupakan bintang sehingga apabila bintang itu hilang maka sebagian besar yang dijanjikan kepada agama akan hilang. Hadis juga menyebut bahwa akan terus ada golongan dari umat Rasulullah yang menegakkan kebenaran dan tidak dibahayakan oleh orang yang menentang mereka hingga datang ketentuan Allah, sehingga generasi yang datang kemudian tetap dapat mencapai kesungguhan yang tinggi. Q.S. al-Hadid [57]: 10 menyebut perbedaan derajat antara orang yang berinfak sebelum penaklukan Makkah dan sesudahnya tetapi menyebut bahwa kepada masing-masing Allah telah menjanjikan kebaikan, sehingga amal generasi yang datang kemudian tetap bernilai.'},
{level:'HOTS',indicator:'Menentukan perilaku meneladani kesungguhan sahabat dalam memanfaatkan waktu muda',text:'Perilaku meneladani kesungguhan para sahabat dalam memanfaatkan waktu muda yang paling tepat bagi seorang pelajar adalah ...',options:['menunda ibadah dan belajar hingga dewasa karena masa muda merupakan masa untuk bersenang-senang','menggunakan masa muda untuk menuntut ilmu dan beribadah','mengisi masa muda dengan kegiatan yang menyenangkan karena masa muda tidak akan kembali','mengisi masa muda dengan bekerja untuk memperoleh penghasilan agar tidak bergantung pada orang tua walaupun mengorbankan waktu belajar'],answer:1,explanation:'Hadis menyebut bahwa tujuh golongan dinaungi Allah pada hari yang tidak ada naungan kecuali naungan-Nya di antaranya pemuda yang tumbuh dalam ibadah kepada Allah. Hadis juga menyebut bahwa tidak akan bergeser kedua kaki seorang hamba pada hari kiamat hingga ditanya tentang empat perkara di antaranya tentang masa mudanya untuk apa digunakan. Hadis menyebut bahwa agama seseorang mengikuti agama sahabat karibnya sehingga hendaklah memperhatikan siapa yang dijadikan sahabat karibnya. Hadis juga menganjurkan menuntut ilmu dan menyebut bahwa barangsiapa menempuh jalan untuk mencari ilmu maka Allah mudahkan baginya jalan menuju surga. Hadis menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga melatih diri dengan tanggung jawab yang sesuai usia merupakan cara membentuk kebiasaan yang berkelanjutan. Adapun bekerja dengan mengorbankan waktu belajar bukan pilihan yang tepat bagi pelajar karena kewajiban belajar pada jenjangnya merupakan persiapan untuk masa depan yang lebih baik.'},
{level:'HOTS',indicator:'Menganalisis pengaruh kesungguhan ibadah sahabat terhadap tersebarnya Islam',text:'Islam tersebar luas setelah Rasulullah wafat melalui usaha para sahabat. Analisis yang paling tepat terhadap pengaruh kesungguhan ibadah mereka terhadap tersebarnya Islam adalah ...',options:['keteladanan akhlak menjadikan ajaran diterima dengan kepercayaan penuh','pengaruh itu terjadi karena para sahabat menguasai bahasa masyarakat yang didakwahi sehingga penyampaiannya mudah dipahami','pengaruh itu terjadi karena masyarakat pada masa itu memerlukan perubahan sehingga menerima ajaran baru apa pun yang disampaikan','pengaruh itu terjadi karena para sahabat memiliki kekuatan pasukan yang besar sehingga dapat menguasai wilayah yang luas'],answer:0,explanation:'Q.S. an-Nahl [16]: 125 memerintahkan menyeru kepada jalan Tuhan dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Q.S. Ali Imran [3]: 159 menyebut bahwa karena rahmat Allah Rasulullah bersikap lemah lembut terhadap mereka dan seandainya bersikap keras dan berhati kasar niscaya mereka menjauh, sehingga kelembutan merupakan sebab diterimanya penyampaian. Q.S. as-Saff [61]: 2-3 mengecam orang yang mengatakan apa yang tidak dikerjakannya, yang menunjukkan bahwa kesesuaian perkataan dan perbuatan merupakan syarat pengaruh penyampaian. Hadis juga menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia. Hadis menyebut bahwa kejujuran membawa kepada kebaikan dan kebaikan membawa ke surga. Q.S. al-Hasyr [59]: 9 menggambarkan kaum Ansar yang mengutamakan orang lain atas diri mereka sendiri, sehingga kedermawanan menjadi teladan yang terlihat. Adapun penguasaan bahasa merupakan sarana yang membantu tetapi bukan sebab utama tersebarnya Islam karena yang paling berpengaruh adalah keteladanan akhlak.'}
]});
